import {editMesh} from '../scene/mesh-edit.js';
import {editorControls,editorAction,editorInput} from './editor.js';import {shapeNodes} from '../scene/shapes.js';
import {escape} from '../renderer/svg.js';import {evaluated,putKey,setProperty,enableTrack} from '../animation/evaluate.js';import {find,animatable,clone,isLocked} from '../document/model.js';import {localBounds,world,point,inverse,multiply,identity} from '../scene/matrix.js';import {locate} from '../document/model.js';
export class Properties{constructor(app,container){this.app=app;this.el=container;container.addEventListener('input',e=>this.input(e));container.addEventListener('change',e=>{if(this.pending)this.flush();else this.change(e);});container.addEventListener('click',e=>{const action=e.target.closest('[data-edit]')?.dataset.edit;if(action)return app.safe(()=>editorAction(app,action));this.key(e);});}
render(){const a=this.app,n=find(a.doc,a.selected[0]);const active=document.activeElement;if(this.currentId===n?.id&&this.el.contains(active)&&active?.matches('[data-prop],[data-mesh-prop],[data-geometry]'))return;this.currentId=n?.id;if(!n){this.el.innerHTML='<div class="empty-properties">Select artwork to change its appearance or add animation.<br><br>Start with a rectangle, circle, or a line of your own.</div>';return;}const v=evaluated(n,a.time);const field=(key,label,opts={})=>`<div class="prop-field ${animatable.includes(key)?'keyable':''} ${opts.full?'full-field':''}"><label>${label}<input data-prop="${key}" type="${opts.type||'number'}" ${opts.type==='color'?'':`step="${opts.step||1}"`} value="${escape(v[key])}" ${opts.min!==undefined?`min="${opts.min}"`:''}></label>${animatable.includes(key)?`<button class="key-button ${n.tracks[key]?.length?'enabled':''}" data-key="${key}" title="${n.tracks[key]?.length?'Add keyframe at the current time':'Enable animation at current time'}" aria-label="Keyframe ${label}">◇</button>`:''}</div>`;this.el.innerHTML=`<input class="property-name" data-prop="name" value="${escape(n.name)}" aria-label="Layer name"><div class="prop-section"><div class="prop-title">Transform</div><div class="prop-grid">${field('x','Position X')}${field('y','Position Y')}${field('width','Width',{min:1})}${field('height','Height',{min:1})}${field('rotation','Rotation °')}${field('opacity','Opacity',{step:.05,min:0})}${field('scaleX','Scale X',{step:.05})}${field('scaleY','Scale Y',{step:.05})}${field('anchorX','Pivot X')}${field('anchorY','Pivot Y')}</div><button id="center-pivot">Center pivot</button></div>${n.type==='group'?'':`<div class="prop-section"><div class="prop-title">Appearance</div><div class="prop-grid">${field('fill','Fill',{type:'color'})}${field('stroke','Stroke',{type:'color'})}${field('strokeWidth','Stroke width',{min:0})}<label class="prop-field">No fill<input type="checkbox" data-no-fill ${n.fill==='none'?'checked':''}></label></div></div>`}${n.type==='text'?`<div class="prop-section"><div class="prop-title">Text</div><div class="prop-grid">${field('text','Content',{type:'text',full:true})}${field('fontSize','Size',{min:1})}<label>Alignment<select data-prop="align">${['left','center','right'].map(x=>`<option ${n.align===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="full-field">Font<select data-prop="font">${['sans-serif','serif','monospace','Arial','Georgia'].map(x=>`<option ${n.font===x?'selected':''}>${x}</option>`).join('')}</select></label></div></div>`:''}${['path','freehand'].includes(n.type)&&!n.rawPath?'<div class="prop-section"><div class="prop-title">Path</div><button id="close-path">'+(n.closed||n.nodes.some(p=>p.close)?'Open path':'Close path')+'</button><button data-key="nodes" class="'+(n.tracks.nodes?.length?'active':'')+'">◇ Keyframe shape</button><p class="subtle">Drag a node or its round Bézier handles. Shape tweens need matching nodes and handles.</p></div>':''}${editorControls(a,n)}<div class="prop-section"><label class="subtle"><input type="checkbox" id="constrain" ${a.constrain?'checked':''}> Constrain proportions</label><label class="subtle"><input type="checkbox" id="from-center" ${a.fromCenter?'checked':''}> Resize from center</label></div><button id="remove-animation">Remove animation tracks</button>`;if(isLocked(a.doc,n.id))this.el.querySelectorAll('input,button,select').forEach(el=>el.disabled=true);this.el.querySelector('#center-pivot').onclick=()=>a.mutate('Center pivot',()=>{const old=point(world(a.doc,n.id,a.time),{x:0,y:0}),b=localBounds(n,a.time);n.anchorX=b.x+b.width/2;n.anchorY=b.y+b.height/2;const now=point(world(a.doc,n.id,a.time),{x:0,y:0}),l=locate(a.doc,n.id),parent=l.parent?world(a.doc,l.parent.id,a.time):identity(),inv=inverse(multiply(parent,n.prefix||identity())),d=point(inv,{x:old.x-now.x,y:old.y-now.y}),zero=point(inv,{x:0,y:0}),v=evaluated(n,a.time);setProperty(n,'x',v.x+d.x-zero.x,a.time);setProperty(n,'y',v.y+d.y-zero.y,a.time);});this.el.querySelector('#constrain').onchange=e=>a.constrain=e.target.checked;this.el.querySelector('#from-center').onchange=e=>a.fromCenter=e.target.checked;this.el.querySelector('#edit-nodes')?.addEventListener('click',()=>{a.nodeEdit=!a.nodeEdit;a.renderStage();});this.el.querySelector('#close-path')?.addEventListener('click',()=>editorAction(a,'toggle-close'));this.el.querySelector('#remove-animation').onclick=()=>a.mutate('Remove animation',()=>{Object.assign(n,evaluated(n,a.time),{tracks:{}});});}
flush(){clearTimeout(this.inputTimer);if(this.pending){this.pending=false;this.app.history.commit('Edit property');}}
input(e){if(editorInput(this,e))return;const key=e.target.dataset.prop;if(!key)return;if(e.target.tagName==='SELECT'){this.flush();return;}if(e.target.type==='checkbox')return;const a=this.app,n=find(a.doc,a.selected[0]);if(!n||isLocked(a.doc,n.id))return;let value=e.target.type==='number'?Number(e.target.value):e.target.value;if(e.target.type==='number'&&(!e.target.value||!Number.isFinite(value)))return;if(key==='opacity')value=Math.max(0,Math.min(1,value));if(['width','height','fontSize'].includes(key))value=Math.max(1,value);if(key==='strokeWidth')value=Math.max(0,value);a.pause();a.history.begin();if(['width','height'].includes(key)&&n.mesh){const axis=key==='width'?'x':'y',f=value/Math.max(.0001,['path','freehand'].includes(n.type)?localBounds(n,a.time)[key]:n[key]);editMesh(n,a.time,m=>{const b=m.bounds;for(const p of m.points)p[axis]=b[axis]+(p[axis]-b[axis])*f;b[key]*=f;return m;});}if(['width','height'].includes(key)&&['path','freehand'].includes(n.type)&&!n.rawPath){const b=localBounds(n,a.time),axis=key==='width'?'x':'y',f=value/Math.max(.0001,b[key]),nodes=clone(evaluated(n,a.time).nodes);for(const p of nodes)for(const q of [p,p.in,p.out].filter(Boolean))q[axis]=b[axis]+(q[axis]-b[axis])*f;setProperty(n,'nodes',nodes,a.time);}setProperty(n,key,value,a.time);if(['fill','stroke'].includes(key))a.rememberColor(value);this.pending=true;a.renderStage();clearTimeout(this.inputTimer);this.inputTimer=setTimeout(()=>this.flush(),500);}
change(e){const a=this.app,n=find(a.doc,a.selected[0]),key=e.target.dataset.prop;if(!n||isLocked(a.doc,n.id))return;if(e.target.hasAttribute('data-no-fill'))return a.mutate('Fill',()=>setProperty(n,'fill',e.target.checked?'none':a.drawColor,a.time));if(!key)return;let value=e.target.type==='number'?Number(e.target.value):e.target.value;if(e.target.type==='number'&&!Number.isFinite(value))return;if(key==='opacity')value=Math.max(0,Math.min(1,value));if(['width','height','fontSize'].includes(key))value=Math.max(1,value);if(key==='strokeWidth')value=Math.max(0,value);a.mutate('Change '+key,()=>{setProperty(n,key,value,a.time);if(['fill','stroke'].includes(key))a.rememberColor(value);});}
key(e){const prop=e.target.closest('[data-key]')?.dataset.key;if(!prop)return;const a=this.app,n=find(a.doc,a.selected[0]);if(n&&!isLocked(a.doc,n.id))a.mutate('Add keyframe',()=>enableTrack(n,prop,a.time,a.ease));}
}

